// The database of mavio.dev (docs/mavio-dev.md §2): better-auth's tables
// (auth-schema.ts, generated by `pnpm run generate-auth-schema`) and
// Mavio's own.
import { relations } from "drizzle-orm";
import { bigint, boolean, customType, index, jsonb, pgTable, primaryKey, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { user } from "./auth-schema.ts";

export * from "./auth-schema.ts";

const bytea = customType<{ data: Uint8Array; driverData: Uint8Array }>({
  dataType: () => "bytea",
  fromDriver: (v) => new Uint8Array(v),
});

const time = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

/** servers are the claimed servers, by the ID of their identity key. */
export const servers = pgTable(
  "servers",
  {
    id: text("id").primaryKey(),
    publicKey: bytea("public_key").notNull(),
    name: text("name").notNull().default(""),
    version: text("version").notNull().default(""),
    // An account administering a server cannot be deleted.
    administratorId: text("administrator_id")
      .notNull()
      .references(() => user.id, { onDelete: "restrict" }),
    // The cursor of the server's latest change.
    cursor: bigint("cursor", { mode: "number" }).notNull().default(0),
    claimedAt: time("claimed_at").notNull(),
  },
  (t) => [index("servers_administrator_id_idx").on(t.administratorId)],
);

/** claimCodes are codes that claim a server for an account, by their SHA-256. */
export const claimCodes = pgTable("claim_codes", {
  codeHash: text("code_hash").primaryKey(),
  accountId: text("account_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  expiresAt: time("expires_at").notNull(),
});

/** serverTokens are the IDs of servers' JWTs, accepted once each until they expire. */
export const serverTokens = pgTable(
  "server_tokens",
  {
    id: text("id").primaryKey(),
    expiresAt: time("expires_at").notNull(),
  },
  (t) => [index("server_tokens_expires_at_idx").on(t.expiresAt)],
);

/** serverLibraries are the libraries servers published. */
export const serverLibraries = pgTable(
  "server_libraries",
  {
    serverId: text("server_id")
      .notNull()
      .references(() => servers.id, { onDelete: "cascade" }),
    id: uuid("id").notNull(),
    name: text("name").notNull(),
    kind: text("kind").notNull(),
  },
  (t) => [primaryKey({ columns: [t.serverId, t.id] })],
);

/**
 * accessRecords are the library access records (docs/accounts.md §3.3):
 * access is a mavio.cloud.v1.Access in protobuf JSON, and a record is an
 * invitation until its account accepts it.
 */
export const accessRecords = pgTable(
  "access_records",
  {
    serverId: text("server_id")
      .notNull()
      .references(() => servers.id, { onDelete: "cascade" }),
    accountId: text("account_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    access: jsonb("access").notNull(),
    invitation: boolean("invitation").notNull(),
    createdAt: time("created_at").notNull(),
    updatedAt: time("updated_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.serverId, t.accountId] }), index("access_records_account_id_idx").on(t.accountId)],
);

/** changes are each server's changes, a mavio.cloud.v1.Change in protobuf JSON by cursor. */
export const changes = pgTable(
  "changes",
  {
    serverId: text("server_id")
      .notNull()
      .references(() => servers.id, { onDelete: "cascade" }),
    cursor: bigint("cursor", { mode: "number" }).notNull(),
    change: jsonb("change").notNull(),
    createdAt: time("created_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.serverId, t.cursor] })],
);

export const serversRelations = relations(servers, ({ one, many }) => ({
  administrator: one(user, { fields: [servers.administratorId], references: [user.id] }),
  libraries: many(serverLibraries),
  accessRecords: many(accessRecords),
}));

export const serverLibrariesRelations = relations(serverLibraries, ({ one }) => ({
  server: one(servers, { fields: [serverLibraries.serverId], references: [servers.id] }),
}));

export const accessRecordsRelations = relations(accessRecords, ({ one }) => ({
  server: one(servers, { fields: [accessRecords.serverId], references: [servers.id] }),
  account: one(user, { fields: [accessRecords.accountId], references: [user.id] }),
}));
